-- StarterGui.VersatileGui.Frame.GunSettings.MultiScript
local function C_f()
local script = G2L["f"];
	local Frame = script.Parent.Parent
	local GunNameBox = Frame:WaitForChild("GunName")
	local button = script.Parent
	local Players = game:GetService("Players")
	local LocalPlayer = Players.LocalPlayer

	local function findGun(gunName)
		if LocalPlayer.Backpack:FindFirstChild(gunName) then
			return LocalPlayer.Backpack[gunName]
		end
		if LocalPlayer.Character and LocalPlayer.Character:FindFirstChild(gunName) then
			return LocalPlayer.Character[gunName]
		end
		return nil
	end

	local function convertValue(v)
		if v == "true" then return true end
		if v == "false" then return false end
		local num = tonumber(v)
		if num ~= nil then return num end
		return v
	end

	button.Activated:Connect(function()
		local gunName = GunNameBox.Text
		if gunName == "" then return end

		local gun = findGun(gunName)
		if not gun then
			warn("Gun not found:", gunName)
			return
		end

		local config = gun:FindFirstChild("GunConfigurations")
		if not config or not config:IsA("ModuleScript") then
			warn("GunConfigurations module missing in gun:", gunName)
			return
		end

		local weaponModule = require(config)

		weaponModule.Bullets = convertValue(Frame.BulletAmount.Text)
		weaponModule.Accuracy = convertValue(Frame.Accuracy.Text)
		weaponModule.BurstRate = convertValue(Frame.BurstFireAmount.Text)
		weaponModule.BurstFire = convertValue(Frame.BurstFire.Text)
		weaponModule.CockAfterShot = convertValue(Frame.CockAfterShot.Text)
		weaponModule.SemiAuto = convertValue(Frame.SemiAuto.Text)
		weaponModule.Recoil = convertValue(Frame.Recoil.Text)
		weaponModule.Firerate = convertValue(Frame.Firerate.Text)
		weaponModule.Range = convertValue(Frame.Range.Text)
		weaponModule.Auto = convertValue(Frame.Automatic.Text)
	end)
end;
task.spawn(C_f);
